import React, { useEffect, useState } from 'react';
import '../styles/home.css';
import { FaHome, FaSearch, FaPaperPlane, FaHeart, FaPlus, FaUser } from 'react-icons/fa';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    setPosts([
      { id: 1, user: 'Aman', content: 'Just got placed at Amazon!', likes: 10, comments: 2 },
      { id: 2, user: 'Simran', content: 'Join my DSA bootcamp!', likes: 5, comments: 1 },
    ]);

    setSuggestions([
      { id: 1, name: 'Harpreet Singh', branch: 'CSE' },
      { id: 2, name: 'Mandeep Kaur', branch: 'IT' },
    ]);
  }, []);

  return (
    <div className="app-container">
      {/* Left Sidebar */}
      <div className="sidebar">
        <h2 className="logo">CampusGram</h2>
        <ul className="nav-menu">
          <li><FaHome /> Home</li>
          <li><FaSearch /> Search</li>
          <li><FaPaperPlane /> Messages</li>
          <li><FaHeart /> Notifications</li>
          <li><FaPlus /> Create</li>
          <li><FaUser /> Profile</li>
        </ul>
      </div>

      {/* Center Content */}
      <div className="main-content">
        <div className="stories">
          {Array(8).fill().map((_, i) => (
            <div key={i} className="story"></div>
          ))}
        </div>

        <div className="feed">
          {posts.map(post => (
            <div className="post-card" key={post.id}>
              <h4>{post.user}</h4>
              <p>{post.content}</p>
              <div className="post-actions">
                <span>❤️ {post.likes}</span>
                <span>💬 {post.comments}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Right Sidebar */}
      <div className="right-sidebar">
        <div className="profile-preview">
          <img src="https://via.placeholder.com/40" alt="user" />
          <div>
            <strong>kaur_ramgariah01</strong>
            <p>Taranpreet</p>
          </div>
        </div>

        <div className="suggestions">
          <h4>Suggested for you</h4>
          {suggestions.map(s => (
            <div key={s.id} className="suggestion">
              <div>
                <p><strong>{s.name}</strong></p>
                <small>{s.branch}</small>
              </div>
              <button>Follow</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;
